-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 10,

        border_size = 2,

        col = {
            active_border   = colors.active,
            inactive_border = colors.inactive,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 12,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled        = true,
            range          = 18,
            render_power   = 3,
            offset         = "0 4",
            color          = colors.shadow,
            color_inactive = colors.shadowInactive,
        },

        blur = {
            enabled           = true,
            size              = 9,      -- radius per pass
            passes            = 4,      -- more passes = stronger, smoother blur
            noise             = 0.015,  -- faint grain, hides banding
            contrast          = 1.0,
            brightness        = 0.9,    -- slightly darker so text on glass stays readable
            vibrancy          = 0.25,   -- keeps wallpaper colors rich through the blur
            vibrancy_darkness = 0.2,
            popups            = true,   -- right-click menus and dropdowns get blur too
            special           = true,   -- blur behind the scratchpad workspace
            new_optimizations = true,
            xray              = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/configuring/core/animations/
-- Curves
hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("linear",       { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",        { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
hl.curve("md3Decel",     { type = "bezier", points = { {0.05, 0.7},  {0.1, 1}     } })  -- Material "emphasized decelerate"
hl.curve("md3Accel",     { type = "bezier", points = { {0.3, 0},     {0.8, 0.15}  } })  -- Material "emphasized accelerate"

-- Springs: "easy" settles smoothly, "bouncy" overshoots a little
hl.curve("easy",   { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })
hl.curve("bouncy", { type = "spring", mass = 1, stiffness = 260,      damping = 19 })

-- Windows: pop in with a little bounce, shrink away quickly, glide when moved
hl.animation({ leaf = "global",      enabled = true, speed = 10,   bezier = "default" })
hl.animation({ leaf = "windows",     enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",   enabled = true, speed = 4.5,  spring = "bouncy",  style = "popin 80%" })
hl.animation({ leaf = "windowsOut",  enabled = true, speed = 2,    bezier = "md3Accel", style = "popin 85%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 4.5,  spring = "easy" })

-- Borders: color fades, and the active window's gradient slowly rotates
hl.animation({ leaf = "border",      enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "borderangle", enabled = true, speed = 80,   bezier = "linear",   style = "loop" })

-- Fades
hl.animation({ leaf = "fadeIn",  enabled = true, speed = 2,    bezier = "md3Decel" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.6,  bezier = "md3Accel" })
hl.animation({ leaf = "fade",    enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "fadeDim", enabled = true, speed = 4,    bezier = "md3Decel" })

-- Layers (bar, popups): Quickshell animates its own popups, see layer rules
hl.animation({ leaf = "layers",        enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 4,    bezier = "md3Decel", style = "slide" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 1.8,  bezier = "md3Accel", style = "slide" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true, speed = 2,    bezier = "md3Decel" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.5,  bezier = "md3Accel" })

-- Workspaces slide horizontally (matches the 3-finger swipe); scratchpad slides vertically
hl.animation({ leaf = "workspaces",       enabled = true, speed = 4, bezier = "md3Decel", style = "slidefade 12%" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 4, bezier = "md3Decel", style = "slidefadevert 20%" })

hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

-- Ref https://wiki.hypr.land/configuring/core/rules/workspace-rules/
-- "Smart gaps" / "No gaps when only"
-- uncomment all if you wish to use that.
