-- See https://wiki.hypr.land/configuring/layouts/dwindle-layout/ for more
hl.config({
    dwindle = {
        preserve_split = true, -- You probably want this
    },
})

-- See https://wiki.hypr.land/configuring/layouts/master-layout/ for more
hl.config({
    master = {
        new_status = "master",
    },
})

-- See https://wiki.hypr.land/configuring/layouts/scrolling-layout/ for more
hl.config({
    scrolling = {
        fullscreen_on_one_column = true,
    },
})

----------------
----  MISC  ----
----------------

hl.config({
    misc = {
        force_default_wallpaper = 0,    -- Quickshell draws the wallpaper
        disable_hyprland_logo   = true,
        allow_session_lock_restore = true,  -- lets a restarted qs re-take the lock if it crashes
    },
})


----------------
---- LAYERS ----
----------------

hl.config({
    layers = {
        allow_new_top_layers_over_existing_fullscreen = true, -- Set to false to make newly mapped top layers render below existing covering fullscreen window
    },
})

-- Blur behind the translucent Quickshell bar. ignore_alpha keeps the
-- fully-transparent rounded corners from being blurred.
hl.layer_rule({
    name  = "blur-rice-bar",
    match = { namespace = "^rice-.*$" },
    blur         = true,
    ignore_alpha = 0.3,
})

hl.layer_rule({
    name      = "bar-slide-in",
    match     = { namespace = "^rice-bar$" },
    animation = "slide top",
})

hl.layer_rule({
    -- these popups have their own QML zoom/slide animations
    name    = "quickshell-popups-no-anim",
    match   = { namespace = "^(rice-(launcher|wallpaper-picker|control-center|notifications|osd|power|polkit|equalizer|clipboard|settings|termdraw|lyrics)|quickshell-.*)$" },
    no_anim = true,
})


