---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
-- Apps
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + SHIFT + RETURN", hl.dsp.exec_cmd("qs ipc call termdraw arm"))  -- draw a terminal
hl.bind(mainMod .. " + T",      hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + SPACE",  hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + D",      hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + R",      hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + W",         hl.dsp.exec_cmd("qs ipc call wallpaper toggle"))
hl.bind(mainMod .. " + A",         hl.dsp.exec_cmd("qs ipc call controlcenter toggle"))
hl.bind(mainMod .. " + SHIFT + A", hl.dsp.exec_cmd("qs ipc call equalizer toggle"))
hl.bind(mainMod .. " + COMMA",     hl.dsp.exec_cmd("qs ipc call settings toggle"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("~/.config/quickshell/scripts/set-wallpaper.sh"))  -- random

-- Windows
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("qs ipc call clipboard toggle"))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Screenshots
hl.bind("Print",                 hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenshot.sh region"))
hl.bind("SHIFT + Print",         hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenshot.sh full"))
hl.bind(mainMod .. " + Print",   hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenshot.sh window"))
hl.bind("ALT + Tab",               hl.dsp.exec_cmd("qs ipc call switcher next"))        -- window switcher (release Alt to switch)
hl.bind("ALT + SHIFT + Tab",       hl.dsp.exec_cmd("qs ipc call switcher prev"))
hl.bind(mainMod .. " + Tab",       hl.dsp.exec_cmd("qs ipc call overview toggle"))      -- workspace overview
hl.bind("ALT + Print",             hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenshot.sh edit"))   -- annotate (needs satty)
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("~/.config/quickshell/scripts/colorpick.sh"))      -- color picker (needs hyprpicker)
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd("~/.config/quickshell/scripts/ocr.sh"))            -- copy text from the screen (needs tesseract)

-- Screen recording (wf-recorder; settings page "Recording")
hl.bind("CTRL + Print",          hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenrec.sh toggle"))
hl.bind("CTRL + ALT + Print",    hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenrec.sh toggle region"))
hl.bind("CTRL + SHIFT + Print",  hl.dsp.exec_cmd("~/.config/quickshell/scripts/screenrec.sh toggle full"))

-- Session
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("qs ipc call lock lock"))
hl.bind("switch:on:Lid Switch", hl.dsp.exec_cmd("qs ipc call lock lock"), { locked = true })
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("qs ipc call power toggle"))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move windows with mainMod + SHIFT + arrow keys
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
-- non_consuming: on empty desktop the click reaches Quickshell, which draws a terminal
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true, non_consuming = true })
-- Wayland doesn't tell the desktop layer that SUPER is held, so tell Quickshell
-- directly; it only acts if the press landed on empty desktop.
hl.bind(mainMod .. " + mouse:272", function() hl.exec_cmd("qs ipc call termdraw superClick") end, { non_consuming = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("qs ipc call brightness up"),                     { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("qs ipc call brightness down"),                   { locked = true, repeating = true })

-- Media keys (handled by Quickshell's MPRIS service)
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("qs ipc call media next"),      { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("qs ipc call media playpause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("qs ipc call media playpause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("qs ipc call media prev"),      { locked = true })


